#include <cstdint>
#include <iostream>

int g_orders = 42;             // data: a global with a starting value
int g_book[1'000'000];         // bss: a global that starts at zero, 4 MB
const char* g_venue = "XNAS";  // the text "XNAS" is in rodata

int lastTick() {               // text: machine code
    return 10;
}

// An address as a plain number, so two addresses can be compared.
std::uintptr_t where(const void* p) {
    return reinterpret_cast<std::uintptr_t>(p);
}

int main() {
    int local = 0;             // stack
    int* order = new int(7);   // heap

    std::uintptr_t text = reinterpret_cast<std::uintptr_t>(&lastTick);
    std::cout << std::boolalpha;
    std::cout << "text < rodata: " << (text < where(g_venue)) << '\n';
    std::cout << "rodata < data: " << (where(g_venue) < where(&g_orders)) << '\n';
    std::cout << "data < bss: " << (where(&g_orders) < where(g_book)) << '\n';
    std::cout << "bss < heap: " << (where(g_book) < where(order)) << '\n';
    std::cout << "heap < stack: " << (where(order) < where(&local)) << '\n';
    std::cout << "g_book[999999]: " << g_book[999'999] << '\n';

    delete order;
    return 0;
}

