#include <cstdint>
#include <iostream>

const int kLimits[3] = {100, 500, 1000};  // a const table
int g_fills[50'000];                      // a global array

int* callCounter() {
    static int calls = 0;  // a static local
    ++calls;
    return &calls;         // safe: calls outlives every call
}

// An address as a plain number, so two addresses can be compared.
std::uintptr_t where(const void* p) {
    return reinterpret_cast<std::uintptr_t>(p);
}

int main() {
    double prices[4] = {1.5, 2.5, 3.5, 4.5};  // a local array
    int* order = new int(7);                  // the heap marker
    std::cout << std::boolalpha;

    std::cout << "kLimits below heap: " << (where(kLimits) < where(order)) << '\n';
    std::cout << "g_fills below heap: " << (where(g_fills) < where(order)) << '\n';
    std::cout << "calls below heap: " << (where(callCounter()) < where(order)) << '\n';
    std::cout << "prices below heap: " << (where(prices) < where(order)) << '\n';
